-- W08 stage 6A: real PostgreSQL authenticated role, synthetic JWT claims.
-- Run ONLY in Development inside BEGIN/ROLLBACK. This does not test signed JWTs,
-- actual HTTP, browser sessions or physical Storage uploads.
CREATE TEMP TABLE qa6_w08_cases(name text primary key) ON COMMIT DROP;
CREATE TEMP TABLE qa6_w08_fixture(b uuid,br uuid,o uuid,v uuid,own text,c1 text,c2 text,rev text,vw text,emp text,unassigned text,suspended text) ON COMMIT DROP;
DO $seed$
DECLARE b uuid:=gen_random_uuid(); br uuid:=gen_random_uuid(); cat uuid:=gen_random_uuid(); o uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); m uuid; suffix text:=substr(md5(random()::text),1,16);
 own text:='qa_6_w08_own_'||suffix; c1 text:='qa_6_w08_c1_'||suffix; c2 text:='qa_6_w08_c2_'||suffix; rev text:='qa_6_w08_rev_'||suffix; vw text:='qa_6_w08_vw_'||suffix; emp text:='qa_6_w08_emp_'||suffix; unassigned text:='qa_6_w08_un_'||suffix; suspended text:='qa_6_w08_sus_'||suffix;
BEGIN
 INSERT INTO public.users(id,account_status) VALUES(own,'active'),(c1,'active'),(c2,'active'),(rev,'active'),(vw,'active'),(emp,'active'),(unassigned,'active'),(suspended,'suspended');
 INSERT INTO wow_private.admin_members(user_id,role,is_active) VALUES(own,'reviewer',true),(rev,'reviewer',true),(vw,'viewer',true);
 INSERT INTO public.categories(id,slug,name_ar,is_active) VALUES(cat,'qa-w08-'||suffix,'تصنيف اختبار',true);
 INSERT INTO public.businesses(id,owner_user_id,name,status,approved_at) VALUES(b,own,'QA W08 rollback fixture','approved',now());
 INSERT INTO public.business_members(business_id,user_id,role,status,can_draft,can_submit,can_pause,can_monitor) VALUES(b,own,'owner','active',true,true,true,true),(b,unassigned,'employee','active',false,false,false,true);
 INSERT INTO public.business_members(business_id,user_id,role,status,can_draft,can_submit,can_pause,can_monitor) VALUES(b,emp,'employee','active',false,false,false,true) RETURNING id INTO m;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 INSERT INTO public.business_categories(business_id,category_id,is_primary,approved_by_user_id) VALUES(b,cat,true,own);
 INSERT INTO public.business_branches(id,business_id,name,city,address_line,status,approved_at) VALUES(br,b,'QA Branch','Aden','QA address','approved',now());
 INSERT INTO public.business_member_branches(member_id,business_id,branch_id) VALUES(m,b,br);
 INSERT INTO public.business_subscriptions(business_id,kind,status,starts_at,ends_at,requested_by_user_id) VALUES(b,'trial','active',now()-interval '1 day',now()+interval '29 days',own);
 INSERT INTO public.offers(id,business_id,created_by_user_id,status,merchant_available) VALUES(o,b,own,'draft',true);
 INSERT INTO public.offer_versions(id,business_id,offer_id,version_no,title,offer_kind,original_price,final_price,currency,starts_at,ends_at,review_status,created_by_user_id,category_id) VALUES(v,b,o,1,'QA W08 offer','product',100,80,'YER',now()-interval '1 day',now()+interval '1 day','draft',own,cat);
 INSERT INTO public.offer_branches(business_id,offer_version_id,branch_id) VALUES(b,v,br);
 UPDATE public.offer_versions SET review_status='pending',submitted_at=now()-interval '2 hours' WHERE id=v;
 UPDATE public.offer_versions SET review_status='approved',approved_at=now()-interval '1 hour' WHERE id=v;
 UPDATE public.offers SET current_version_id=v,status='active' WHERE id=o;
 INSERT INTO qa6_w08_fixture VALUES(b,br,o,v,own,c1,c2,rev,vw,emp,unassigned,suspended);
END $seed$;
GRANT SELECT ON qa6_w08_fixture TO authenticated;
GRANT SELECT,INSERT ON qa6_w08_cases TO authenticated;
SET LOCAL ROLE authenticated;
DO $test$
DECLARE f qa6_w08_fixture%ROWTYPE; cid uuid; rid uuid; r2 uuid; d jsonb; marker text:='QA customer confidential marker'; internal_note text:='QA internal only reviewer note'; reply text:='QA proprietor answer for reviewer';
BEGIN
 SELECT * INTO f FROM qa6_w08_fixture;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.c1,'role','authenticated')::text,true);
 rid:=public.wow_rate_offer(f.o,'matches',4::smallint);
 IF rid IS NULL THEN RAISE EXCEPTION 'rating submission failed'; END IF;
 INSERT INTO qa6_w08_cases VALUES('customer-rating-created');
 r2:=public.wow_rate_offer(f.o,'does_not_match',2::smallint);
 IF r2 IS DISTINCT FROM rid OR jsonb_array_length(public.wow_get_my_ratings(100,0))<>1 THEN RAISE EXCEPTION 'duplicate rating'; END IF;
 INSERT INTO qa6_w08_cases VALUES('rating-update-idempotent');
 BEGIN PERFORM public.wow_rate_offer(f.o,'could_not_verify',3::smallint); RAISE EXCEPTION 'invalid rating accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('invalid-rating-denied');
 cid:=public.wow_submit_complaint(f.o,'price_mismatch',marker,f.v,f.br,NULL,'[]'::jsonb);
 IF cid IS NULL THEN RAISE EXCEPTION 'complaint submission failed'; END IF;
 d:=public.wow_get_my_complaints(100,0);
 IF d->0->>'id' IS DISTINCT FROM cid::text OR d->0->>'description' IS DISTINCT FROM marker THEN RAISE EXCEPTION 'customer complaint not returned'; END IF;
 INSERT INTO qa6_w08_cases VALUES('customer-complaint-created-and-tracked');
 BEGIN PERFORM public.wow_submit_complaint(f.o,'other',marker,f.v,gen_random_uuid(),NULL,'[]'::jsonb); RAISE EXCEPTION 'wrong branch accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('wrong-branch-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.c2,'role','authenticated')::text,true);
 IF public.wow_get_my_complaints(100,0) IS DISTINCT FROM '[]'::jsonb OR public.wow_get_my_ratings(100,0) IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'cross-customer leak'; END IF;
 INSERT INTO qa6_w08_cases VALUES('cross-customer-isolation');
 IF public.wow_merchant_get_complaint(cid) IS NOT NULL THEN RAISE EXCEPTION 'nonmember merchant read'; END IF;
 INSERT INTO qa6_w08_cases VALUES('nonmember-merchant-denied');
 BEGIN PERFORM public.wow_admin_get_complaint(cid); RAISE EXCEPTION 'customer admin read'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('customer-admin-read-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.suspended,'role','authenticated')::text,true);
 BEGIN PERFORM public.wow_get_my_complaints(100,0); RAISE EXCEPTION 'suspended read'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.wow_rate_offer(f.o,'matches',4::smallint); RAISE EXCEPTION 'suspended rating'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('suspended-read-write-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.own,'role','authenticated')::text,true);
 d:=public.wow_merchant_get_complaint(cid);
 IF d->>'id' IS DISTINCT FROM cid::text OR d::text LIKE '%'||marker||'%' OR d ? 'user_id' THEN RAISE EXCEPTION 'merchant privacy projection failed'; END IF;
 INSERT INTO qa6_w08_cases VALUES('owner-sanitized-complaint');
 BEGIN PERFORM public.wow_merchant_respond_complaint(cid,reply); RAISE EXCEPTION 'response without request accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('unsolicited-response-denied');
 BEGIN PERFORM public.wow_admin_request_merchant_response(cid,'QA conflicted request'); RAISE EXCEPTION 'conflict request allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.wow_admin_moderate_rating(rid,'excluded','QA conflicted decision'); RAISE EXCEPTION 'conflict moderation allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('affiliated-admin-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.emp,'role','authenticated')::text,true);
 d:=public.wow_merchant_get_complaint(cid);
 IF d->>'id' IS DISTINCT FROM cid::text OR d::text LIKE '%'||marker||'%' OR d->'updates' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'assigned monitor projection'; END IF;
 INSERT INTO qa6_w08_cases VALUES('assigned-employee-sanitized-read');
 BEGIN PERFORM public.wow_merchant_respond_complaint(cid,reply); RAISE EXCEPTION 'employee response'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('employee-response-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.unassigned,'role','authenticated')::text,true);
 IF public.wow_merchant_get_complaint(cid) IS NOT NULL THEN RAISE EXCEPTION 'unassigned employee read'; END IF;
 INSERT INTO qa6_w08_cases VALUES('unassigned-employee-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.vw,'role','authenticated')::text,true);
 d:=public.wow_admin_get_complaint(cid);
 IF d #>> '{complaint,id}' IS DISTINCT FROM cid::text OR (d->'complaint') ? 'private_evidence_keys' THEN RAISE EXCEPTION 'viewer projection failed'; END IF;
 INSERT INTO qa6_w08_cases VALUES('viewer-evidence-key-redacted');
 BEGIN PERFORM public.wow_admin_update_complaint(cid,'investigating',internal_note,NULL); RAISE EXCEPTION 'viewer decision allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('viewer-decision-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.rev,'role','authenticated')::text,true);
 IF public.wow_admin_update_complaint(cid,'investigating',internal_note,NULL) IS DISTINCT FROM cid THEN RAISE EXCEPTION 'investigate failed'; END IF;
 IF public.wow_admin_request_merchant_response(cid,'QA please explain price discrepancy') IS NULL THEN RAISE EXCEPTION 'request failed'; END IF;
 d:=public.wow_admin_get_complaint(cid);
 IF d #>> '{complaint,status}' IS DISTINCT FROM 'waiting' THEN RAISE EXCEPTION 'waiting not persisted'; END IF;
 INSERT INTO qa6_w08_cases VALUES('reviewer-request-workflow');
 BEGIN PERFORM public.wow_admin_request_merchant_response(cid,'QA duplicate request'); RAISE EXCEPTION 'duplicate request allowed'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('duplicate-request-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.own,'role','authenticated')::text,true);
 d:=public.wow_merchant_get_complaint(cid);
 IF d->>'status' IS DISTINCT FROM 'waiting' OR d::text LIKE '%'||internal_note||'%' OR d::text NOT LIKE '%QA please explain price discrepancy%' THEN RAISE EXCEPTION 'request visibility invalid'; END IF;
 IF public.wow_merchant_respond_complaint(cid,reply) IS NULL THEN RAISE EXCEPTION 'response failed'; END IF;
 d:=public.wow_merchant_get_complaint(cid);
 IF d->>'status' IS DISTINCT FROM 'investigating' THEN RAISE EXCEPTION 'response transition failed'; END IF;
 INSERT INTO qa6_w08_cases VALUES('owner-response-and-private-note-isolation');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.rev,'role','authenticated')::text,true);
 IF public.wow_admin_moderate_rating(rid,'excluded','QA moderation reason') IS DISTINCT FROM rid THEN RAISE EXCEPTION 'rating moderation failed'; END IF;
 IF public.wow_admin_update_complaint(cid,'closed',internal_note,'QA customer safe resolution') IS DISTINCT FROM cid THEN RAISE EXCEPTION 'close failed'; END IF;
 INSERT INTO qa6_w08_cases VALUES('reviewer-closes-and-moderates');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.c1,'role','authenticated')::text,true);
 d:=public.wow_get_my_complaints(100,0);
 IF d->0->>'status' IS DISTINCT FROM 'closed' OR d->0->>'public_outcome' IS DISTINCT FROM 'QA customer safe resolution' OR d::text LIKE '%'||internal_note||'%' OR d::text LIKE '%'||reply||'%' THEN RAISE EXCEPTION 'customer final view leak or wrong status'; END IF;
 INSERT INTO qa6_w08_cases VALUES('customer-safe-closure');
 IF public.wow_rate_offer(f.o,'matches',5::smallint) IS DISTINCT FROM rid THEN RAISE EXCEPTION 'rating update after moderation failed'; END IF;
 d:=public.wow_get_my_ratings(100,0);
 IF d->0->>'moderation_status' IS DISTINCT FROM 'excluded' THEN RAISE EXCEPTION 'rating edit bypassed moderation'; END IF;
 INSERT INTO qa6_w08_cases VALUES('rating-edit-preserves-moderation');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f.own,'role','authenticated')::text,true);
 BEGIN PERFORM public.wow_merchant_respond_complaint(cid,reply); RAISE EXCEPTION 'closed complaint accepted response'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO qa6_w08_cases VALUES('closed-response-denied');
END $test$;
RESET ROLE;
SELECT count(*) AS passed,jsonb_agg(name ORDER BY name) AS cases FROM qa6_w08_cases;
